const webhook = $('Webhook').first().json;
const args = webhook.body.args;
const showroom = $('Find Showroom for Test Drive').first().json;
const model = $('Find Model for Test Drive').first().json;
const booking = $('Insert Test Drive Request').first().json;

return [{
  json: {
    response: `Excellent! I've booked your test drive for the ${model.name} at our ${showroom.name} showroom. Our team will call you at ${args.customer_phone} shortly to confirm the exact timing. Is there anything else you'd like to know about the ${model.name}?`,
    data: {
      booking_id: booking.id,
      status: booking.status,
      model: model.name,
      showroom: showroom.name,
      showroom_address: showroom.address,
      showroom_phone: showroom.phone,
      customer_name: args.customer_name,
      customer_phone: args.customer_phone,
      city: args.city
    }
  }
}];

const model = $input.first().json;
const args = $('Webhook').first().json.body.args;

if (!model || !model.name) {
  return [{
    json: {
      response: `Sorry, I couldn't find specifications for ${args.model_name}. Please check the model name.`
    }
  }];
}

let response = `The ${model.name} is a ${model.category.toLowerCase()}. `;

if (model.engine_cc) {
  response += `It has a ${model.engine_cc}cc engine. `;
}
if (model.mileage_kmpl) {
  response += `Mileage is ${model.mileage_kmpl} kmpl. `;
}
if (model.top_speed_kmph) {
  response += `Top speed is ${model.top_speed_kmph} kmph. `;
}

const price = new Intl.NumberFormat('en-IN').format(model.ex_showroom_price_base);
response += `Starting price is ₹${price} ex-showroom. Would you like to know the on-road price in your city?`;

return [{
  json: { response }
}];

