const webhook = $('Webhook').first().json;
const args = webhook.body.args;

// Get callback data from either path
let callbackData;
try {
  callbackData = $('Insert Callback With Client').first()?.json;
} catch(e) {
  callbackData = $('Insert Callback Without Client').first()?.json;
}

const reason = args.reason || '';
const isFinanceRelated = reason.toLowerCase().includes('emi') || reason.toLowerCase().includes('finance') || reason.toLowerCase().includes('loan');

let helpText = 'your request';
if (isFinanceRelated) {
  helpText = 'all the financing options';
}

return [{
  json: {
    response: `I completely understand. I've flagged this for our team and they will call you back at ${args.customer_phone} within 30 minutes. They'll be able to help you with ${helpText}. Is there anything else I can help you with in the meantime?`,
    data: {
      callback_id: callbackData?.id,
      status: 'pending',
      priority: args.priority || 'normal',
      estimated_callback: 'within 30 minutes',
      customer_phone: args.customer_phone
    }
  }
}];
